// Bridges this app's export style to what the converter can read.
//
// Produces two generated files:
//
// 1. `.design-sync/.cache/named-defaults.ts` — wired in via cfg.extraEntries.
//    The synthesized bundle entry is `export * from "<file>"` per source file,
//    and `export *` never re-exports a default. 94 of the 110 component files
//    here use `export default`, so without this they compile into the bundle but
//    are unreachable: `[BUNDLE_EXPORT] 93/144 not a component on window.TixHub`.
//
// 2. `dist/types/index.d.ts` — the barrel `lib/dts.mjs` reads props from.
//    Extraction is `project.getSourceFile(entry).getExportedDeclarations()`,
//    where entry is `<pkgDir>/<pkgJson.types>`; with no barrel every component
//    emits an empty `[key: string]: unknown` props stub. `prepare-pkgdir.mjs`
//    points `types` here.
import { existsSync, mkdirSync, readFileSync, readdirSync, statSync, writeFileSync } from 'node:fs';
import { basename, dirname, join, relative } from 'node:path';
import { fileURLToPath } from 'node:url';

const repo = dirname(dirname(fileURLToPath(import.meta.url)));
const compDir = join(repo, 'src', 'components');
const dtsRoot = join(repo, 'dist', 'types');
const outFile = join(repo, '.design-sync', '.cache', 'named-defaults.ts');

const walk = (dir) => readdirSync(dir).flatMap((n) => {
  const p = join(dir, n);
  return statSync(p).isDirectory() ? walk(p) : [p];
});

const files = walk(compDir).filter((p) => /\.tsx$/.test(p) && !/\.(test|spec|stories)\./.test(p));

// Every PascalCase name the files already export directly. A default aliased to
// a name that also exists as a named export would collide: ESM resolves an
// ambiguous star re-export to undefined, silently emptying BOTH.
const namedExports = new Set();
for (const f of files) {
  const text = readFileSync(f, 'utf8');
  for (const m of text.matchAll(/^export\s+(?:async\s+)?(?:function|const|class|let|var)\s+([A-Z][A-Za-z0-9]*)/gm)) namedExports.add(m[1]);
  for (const m of text.matchAll(/^export\s*\{([^}]*)\}/gm)) {
    for (const part of m[1].split(',')) {
      const name = part.split(/\s+as\s+/).pop().trim();
      if (/^[A-Z][A-Za-z0-9]*$/.test(name)) namedExports.add(name);
    }
  }
}

const runtime = [];
const barrel = [];
const collisions = [];
let defaults = 0;

for (const f of files) {
  const relSrc = relative(repo, f).split('\\').join('/');
  const dtsPath = join(dtsRoot, relSrc.replace(/\.tsx$/, '.d.ts'));
  const dtsSpec = './' + relSrc.replace(/\.tsx$/, '');
  const hasDts = existsSync(dtsPath);

  // Named exports reach both the bundle and the barrel on their own.
  if (hasDts) barrel.push(`export * from ${JSON.stringify(dtsSpec)};`);

  if (!/^export default/m.test(readFileSync(f, 'utf8'))) continue;
  const name = basename(f, '.tsx');
  if (!/^[A-Z][A-Za-z0-9]*$/.test(name)) { collisions.push(`${name} (not PascalCase) — ${relSrc}`); continue; }
  if (namedExports.has(name)) { collisions.push(`${name} (already a named export) — ${relSrc}`); continue; }
  runtime.push(`export { default as ${name} } from ${JSON.stringify(f)};`);
  if (hasDts) barrel.push(`export { default as ${name} } from ${JSON.stringify(dtsSpec)};`);
  defaults++;
}

mkdirSync(dirname(outFile), { recursive: true });
writeFileSync(outFile, `// Generated by .design-sync/prepare-defaults.mjs — do not edit.\n${runtime.join('\n')}\n`);
console.error(`✓ ${defaults} default export(s) named → .design-sync/.cache/named-defaults.ts`);

if (existsSync(dtsRoot)) {
  writeFileSync(join(dtsRoot, 'index.d.ts'), `// Generated by .design-sync/prepare-defaults.mjs — do not edit.\n${barrel.join('\n')}\n`);
  console.error(`✓ ${barrel.length} re-export(s) → dist/types/index.d.ts (props barrel)`);
} else {
  console.error('! dist/types missing — run the tsc declaration step first, or every props body stays a stub');
}
if (collisions.length) {
  console.error(`! skipped ${collisions.length} (would collide on the global):`);
  for (const c of collisions) console.error(`    ${c}`);
}
